SELECT id AS event_id,timestamp AS occurred_at,environment AS environment,event_type AS event_type,JSONExtract(event,'userId','Nullable(String)') AS user_id,JSONExtract(event,'clientId','Nullable(String)') AS client_id,JSONExtract(event,'sessionId','Nullable(String)') AS session_id,JSONExtract(event,'tabId','Nullable(String)') AS tab_id,replaceRegexpOne(CASE WHEN event_type='navigate' THEN JSONExtract(event,'to','Nullable(String)') WHEN event_type='pageLoadFinished' THEN JSONExtract(event,'url','Nullable(String)') ELSE JSONExtract(event,'path','Nullable(String)') END,'^https?://[^/]+','') AS path,JSONExtract(event,'feedItemId','Nullable(String)') AS feed_item_id,if(JSONType(event,'expansionLevel')='Null',NULL,toDecimal128(if(JSONType(event,'expansionLevel')='String',JSONExtractString(event,'expansionLevel'),JSONExtractRaw(event,'expansionLevel')),6)) AS expansion_level,JSONExtract(event,'userAgent','Nullable(String)') AS user_agent,JSONExtract(event,'abTestGroups','welcomeBoxABTest','Nullable(String)') AS ab_variant FROM benchmark_full_20260910.raw_snapshot;
